import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Arquitetura","description":"","frontmatter":{"status":"rascunho","tipo":"arquitetura","atualizado_em":"2026-08-03T00:00:00.000Z"},"headers":[],"relativePath":"planejamento/arquitetura.md","filePath":"planejamento/arquitetura.md","lastUpdated":null}'),i={name:"planejamento/arquitetura.md"};function l(d,a,s,c,n,p){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="arquitetura" tabindex="-1">Arquitetura <a class="header-anchor" href="#arquitetura" aria-label="Permalink to &quot;Arquitetura&quot;">​</a></h1><p>Esta pagina resume a arquitetura geral do Akiba. Para exemplos de estrutura interna de cada arquivo, consulte <a href="./desenvolvimento/padroes-de-arquivos">desenvolvimento/padroes-de-arquivos</a>.</p><h2 id="stack" tabindex="-1">Stack <a class="header-anchor" href="#stack" aria-label="Permalink to &quot;Stack&quot;">​</a></h2><ul><li>Backend: Laravel 12 com PHP 8.2.</li><li>Frontend: Svelte com Inertia e Vite.</li><li>Estilo: Tailwind CSS.</li><li>Banco de dados: MySQL 8.</li><li>Autenticacao: Laravel Sanctum e fluxo privado do painel.</li></ul><h2 id="estrutura-principal" tabindex="-1">Estrutura Principal <a class="header-anchor" href="#estrutura-principal" aria-label="Permalink to &quot;Estrutura Principal&quot;">​</a></h2><ul><li><code>app/Http/Controllers/Public</code>: controllers da area publica.</li><li><code>app/Http/Controllers/Private</code>: controllers do painel privado.</li><li><code>app/Http/Controllers/Private/Pages</code>: controllers que renderizam paginas Inertia.</li><li><code>app/Http/Controllers/Private/Invokes</code>: controllers de acoes pontuais.</li><li><code>app/Actions</code>: regras de negocio por modulo.</li><li><code>app/Filters</code>: filtros de consulta.</li><li><code>app/Http/Requests</code>: validacoes de entrada.</li><li><code>app/Http/Resources</code>: formato de retorno para dados enviados ao frontend.</li><li><code>resources/js/pages/private</code>: paginas privadas em Svelte.</li><li><code>resources/js/pages/public</code>: paginas publicas em Svelte.</li></ul><h2 id="padrao-de-controllers" tabindex="-1">Padrao de Controllers <a class="header-anchor" href="#padrao-de-controllers" aria-label="Permalink to &quot;Padrao de Controllers&quot;">​</a></h2><p>Controllers de renderizacao devem concentrar a composicao de props da pagina e delegar consultas para filters.</p><p>Controllers de CRUD devem ser finos:</p><ul><li>validar entrada via Request;</li><li>autorizar operacao;</li><li>chamar Action;</li><li>retornar resposta Inertia ou redirect.</li></ul><p>Controllers invocaveis devem representar acoes especificas que nao se encaixam em CRUD tradicional, como concluir tarefa, desativar item ou alterar status.</p><h2 id="padrao-de-actions" tabindex="-1">Padrao de Actions <a class="header-anchor" href="#padrao-de-actions" aria-label="Permalink to &quot;Padrao de Actions&quot;">​</a></h2><p>Actions devem concentrar mudancas de estado e regras de negocio. Quando uma operacao tocar multiplas tabelas ou tiver passos encadeados, deve usar transacao.</p><h2 id="padrao-de-filters" tabindex="-1">Padrao de Filters <a class="header-anchor" href="#padrao-de-filters" aria-label="Permalink to &quot;Padrao de Filters&quot;">​</a></h2><p>Filters devem receber parametros em array e compor queries com condicionais claras. O objetivo e manter controllers sem detalhes excessivos de consulta.</p><h2 id="ordem-de-implementacao" tabindex="-1">Ordem de Implementacao <a class="header-anchor" href="#ordem-de-implementacao" aria-label="Permalink to &quot;Ordem de Implementacao&quot;">​</a></h2><p>Ao criar ou alterar uma funcionalidade, siga esta ordem:</p><ol><li>Rota em <code>routes/web</code> ou <code>routes/api.php</code>.</li><li>Controller de pagina, CRUD ou acao invocavel.</li><li>Request para validar entrada e checar autorizacao.</li><li>Action para executar regra de negocio.</li><li>Filter quando a tela precisar de listagem pesquisavel ou paginada.</li><li>Resource para formatar dados enviados ao frontend.</li><li>Pagina Svelte em <code>resources/js/pages</code>.</li><li>Componentes ou widgets reutilizaveis em <code>resources/js/lib</code>.</li></ol><p>Essa ordem ajuda a manter cada arquivo com uma responsabilidade clara e facilita revisar PRs.</p>',19)])])}const v=e(i,[["render",l]]);export{m as __pageData,v as default};
